use MyInvoice\Tests\Integration\Property\Services\Settlement\ServiceLifecycleNativeTest;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
final class ServiceReconciliationNativeTest extends TestCase
{
    private ServiceLifecycleNativeTest $fixture;
    private Connection $db;
    protected function setUp():void{$this->fixture=new ServiceLifecycleNativeTest('testNativeBalanceYearRolloverUnwindsExactEstimateAndFinalizes');(new \ReflectionMethod($this->fixture,'setUp'))->invoke($this->fixture);$this->db=(new \ReflectionProperty($this->fixture,'db'))->getValue($this->fixture);}
    protected function tearDown():void{if(isset($this->fixture))(new \ReflectionMethod($this->fixture,'tearDown'))->invoke($this->fixture);}
    private function native(string $method,mixed ...$args):mixed{return(new \ReflectionMethod($this->fixture,$method))->invoke($this->fixture,...$args);}
    public static function policies():array{return ['balance'=>['service_balance_sheet'],'result'=>['service_profit_and_loss']];}
    #[DataProvider('policies')]
    public function testHistoricalOpeningEstimateFinalInvoiceSettlementAndTypedReverseReconcileAtTheirOwnDates(string $policy):void
    {
        $d=$this->native('openingBase',$policy,false);$f=$d['f'];$s=$f['supplier'];$read=new ServiceReconciliation($this->db);$before=$read->at($s,'2027-03-31');self::assertTrue($before['matches'],json_encode($before));self::assertSame('12000000',$before['totals']['324.110']);self::assertSame('11000000',$before['totals']['388.210']);self::assertSame('11000000',$before['totals']['389.110']);$invoice=$this->native('invoice',$d);$d['owner']->unwind($s,$d['case'],'2027-04-01',$f['actor']);$final=$d['owner']->finalize($s,$d['case'],$invoice['invoice'],$invoice['line']['id'],'2027-04-01','Synthetic canonical service result',$f['actor']);
        $historical=$read->at($s,'2027-03-31',$f['units']['U02'],$f['service']['id']);self::assertTrue($historical['matches'],json_encode($historical));self::assertSame($before['totals'],$historical['totals']);$unsettled=$read->at($s,'2027-04-01');self::assertTrue($unsettled['matches'],json_encode($unsettled));self::assertSame('11200000',$unsettled['totals']['315.210']);self::assertSame('0',$unsettled['totals']['388.210']);self::assertSame('0',$unsettled['totals']['389.110']);if($policy==='service_profit_and_loss'){self::assertSame('200000',$unsettled['totals']['502']);self::assertSame('200000',$unsettled['totals']['649']);}
        $done=$this->native('applySettlement',$d,$final['cost_line_id'],$d['paid'],false);$settled=$read->at($s,'2027-04-01');self::assertTrue($settled['matches'],json_encode($settled));foreach(['315.210','324.110','388.210','389.110'] as $account)self::assertSame('0',$settled['totals'][$account]);$container=(new \ReflectionProperty($this->fixture,'container'))->getValue($this->fixture);$container->get(\MyInvoice\Repository\Property\Services\Settlement\SettlementApplicationRepository::class)->reverse($s,$done['id'],'2027-04-02',1,'Synthetic canonical reverse','recon-reverse',$f['actor']);$past=$read->at($s,'2027-04-01');self::assertTrue($past['matches'],json_encode($past));self::assertSame($settled['totals'],$past['totals']);$reversed=$read->at($s,'2027-04-02');self::assertTrue($reversed['matches'],json_encode($reversed));self::assertSame($unsettled['totals'],$reversed['totals']);
    }
    public function testKnowledgeCutoffIsExplicitlyUnsupported():void
    {
        $d=$this->native('openingBase','service_balance_sheet',false);try{(new ServiceReconciliation($this->db))->at($d['f']['supplier'],'2027-03-31',null,null,'2027-03-31T23:59:59+02:00');self::fail('Current source proof was presented as historical knowledge.');}catch(ServiceReconciliationException $error){self::assertSame('property_service_reconciliation_known_at_unsupported',$error->errorCode);self::assertSame(409,$error->status);}
    }

    #[DataProvider('policies')]
    public function testNativeIssuedAdvancesAndProvenAnnualCarryRemainSingleCounted(string $policy):void
    {
        $d=$this->native('base',$policy);$f=$d['f'];$read=new ServiceReconciliation($this->db);$before=$read->at($f['supplier'],'2026-12-31');self::assertTrue($before['matches'],json_encode($before));self::assertSame('13200000',$before['totals']['324.110']);self::assertSame('1100000',$before['totals']['388.210']);self::assertSame('1100000',$before['totals']['389.110']);self::assertSame('0',$before['totals']['315.210']);self::assertNotEmpty($before['verified_carry_entry_ids']);$next=$read->at($f['supplier'],'2027-01-01');self::assertTrue($next['matches'],json_encode($next));foreach(['324.110','388.210','389.110','315.210'] as $account)self::assertSame($before['totals'][$account],$next['totals'][$account]);self::assertGreaterThan(count($before['verified_carry_entry_ids']),count($next['verified_carry_entry_ids']));if($policy==='service_profit_and_loss'){self::assertSame('1100000',$before['totals']['502']);self::assertArrayNotHasKey('502',$next['totals']);}
        $invoice=$this->native('invoice',$d);$d['owner']->unwind($f['supplier'],$d['case'],'2027-04-01',$f['actor']);$done=$d['owner']->finalize($f['supplier'],$d['case'],$invoice['invoice'],$invoice['line']['id'],'2027-04-01','Synthetic final native cost',$f['actor']);$after=$read->at($f['supplier'],'2027-04-01');self::assertTrue($after['matches'],json_encode($after));self::assertSame('1120000',$after['totals']['315.210']);self::assertSame('0',$after['totals']['388.210']);self::assertSame('0',$after['totals']['389.110']);if($policy==='service_profit_and_loss'){self::assertSame('20000',$after['totals']['502']);self::assertSame('20000',$after['totals']['649']);}$this->native('applySettlement',$d,$done['cost_line_id'],'0',false);$unit=$read->at($f['supplier'],'2027-04-01',$f['units']['U02'],$f['service']['id']);self::assertTrue($unit['matches'],json_encode($unit));foreach(['324.110','388.210','389.110','315.210'] as $account)self::assertSame('0',$unit['totals'][$account]);
    }
    private function orphan(array $d):int
    {
        $container=(new \ReflectionProperty($this->fixture,'container'))->getValue($this->fixture);$dims=$d['dims'];$origins=array_fill_keys(array_keys($dims),['origin'=>'explicit','ref'=>null]);return $container->get(\MyInvoice\Service\Accounting\PostingService::class)->postDocument($d['f']['supplier'],'manual',null,[['account_code'=>'315.210','side'=>'debit','amount'=>'1.00','dimensions'=>$dims,'dimension_origins'=>$origins],['account_code'=>'321','side'=>'credit','amount'=>'1.00','dimensions'=>$dims,'dimension_origins'=>$origins]],['entry_date'=>'2027-03-01','posted_by'=>$d['f']['actor']]);
    }
    public function testBalancedOrphanAndTypedReversalCannotHideBehindZeroNetDifference():void
    {
        $d=$this->native('openingBase','service_balance_sheet',false);$entry=$this->orphan($d);$container=(new \ReflectionProperty($this->fixture,'container'))->getValue($this->fixture);$container->get(\MyInvoice\Service\Accounting\PostingService::class)->reverse($d['f']['supplier'],$entry,['entry_date'=>'2027-03-02','posted_by'=>$d['f']['actor']]);$result=(new ServiceReconciliation($this->db))->at($d['f']['supplier'],'2027-03-31',$d['f']['units']['U02'],$d['f']['service']['id']);self::assertSame($result['totals'],$result['ledger_totals']);self::assertFalse($result['matches']);self::assertSame('incomplete',$result['coverage']);self::assertCount(2,$result['unregistered_line_ids']);self::assertContains('ledger_source_missing',array_column($result['incomplete'],'code'));
    }
    public function testPendingOpeningEstimateReceiptCannotMasqueradeAsProvenZero():void
    {
        $d=$this->native('openingBase','service_balance_sheet',false);$this->db->pdo()->prepare("UPDATE property_service_lifecycle_events SET receipt_json=NULL,receipt_hash=NULL WHERE supplier_id=? AND case_id=? AND event_key='estimate'")->execute([$d['f']['supplier'],$d['case']]);$result=(new ServiceReconciliation($this->db))->at($d['f']['supplier'],'2027-03-31');self::assertSame($result['totals'],$result['ledger_totals']);self::assertFalse($result['matches']);self::assertSame('incomplete',$result['coverage']);self::assertContains('lifecycle_pending',array_column($result['incomplete'],'code'));
    }

    public function testMissingLedgerDimensionsAreVisibleInsideSelectedUnitScope():void
    {
        $d=$this->native('openingBase','service_balance_sheet',false);$entry=$this->orphan($d);$q=$this->db->pdo()->prepare("SELECT l.id FROM journal_entry_lines l JOIN chart_of_accounts c ON c.id=l.account_id AND c.supplier_id=l.supplier_id WHERE l.supplier_id=? AND l.entry_id=? AND c.account_code='315.210'");$q->execute([$d['f']['supplier'],$entry]);$line=(int)$q->fetchColumn();$this->db->pdo()->prepare('DELETE FROM journal_entry_line_dimensions WHERE supplier_id=? AND line_id=?')->execute([$d['f']['supplier'],$line]);$result=(new ServiceReconciliation($this->db))->at($d['f']['supplier'],'2027-03-31',$d['f']['units']['U02'],$d['f']['service']['id']);self::assertFalse($result['matches']);self::assertContains($line,$result['unregistered_line_ids']);self::assertContains('ledger_scope',array_column($result['incomplete'],'code'));
    }
    public function testCanonicalOpeningLedgerTamperFailsClosed():void
    {
        $d=$this->native('openingBase','service_balance_sheet',false);$q=$this->db->pdo()->prepare("UPDATE journal_entry_lines l JOIN chart_of_accounts c ON c.supplier_id=l.supplier_id AND c.id=l.account_id SET l.amount=l.amount+0.01 WHERE l.supplier_id=? AND l.entry_id=? AND c.account_code='388.210'");$q->execute([$d['f']['supplier'],$d['batch']['journal_entry_id']]);self::assertSame(1,$q->rowCount());try{(new ServiceReconciliation($this->db))->at($d['f']['supplier'],'2027-03-31');self::fail('Changed canonical opening ledger accepted');}catch(\MyInvoice\Service\Property\Opening\OpeningException $error){self::assertSame('property_opening_ledger_changed',$error->errorCode);}
    }
    public function testForeignUnitScopeIsRejected():void
    {
        $d=$this->native('openingBase','service_balance_sheet',false);try{(new ServiceReconciliation($this->db))->at($d['f']['supplier'],'2027-03-31',PHP_INT_MAX);self::fail('Foreign unit accepted');}catch(ServiceReconciliationException $error){self::assertSame('property_service_reconciliation_foreign_scope',$error->errorCode);}
    }

    public function testReferenceKnownEightyThousandAndEstimateFiftyThousandRemainIndependentSources():void
    {
        $cross=(new \ReflectionProperty($this->fixture,'fixture'))->getValue($this->fixture);$d=(new \ReflectionMethod($cross,'nativeFixture'))->invoke($cross,'8000000');$f=$d['f'];$container=(new \ReflectionProperty($this->fixture,'container'))->getValue($this->fixture);$chart=new \MyInvoice\Repository\ChartOfAccountsRepository($this->db);foreach(['388.210','389.110'] as $code)if(!$chart->findByCode($f['supplier'],$code)){$parent=$chart->findByCode($f['supplier'],substr($code,0,3));$chart->insert($f['supplier'],['account_code'=>$code,'name'=>'Synthetic reference accrual','account_type'=>$parent['account_type'],'normal_side'=>$parent['normal_side'],'parent_id'=>$parent['id']]);}
        $dims=$d['doc']->snapshot()['cost']['line']['dimensions'];$origins=array_fill_keys(array_keys($dims),['origin'=>'explicit','ref'=>null]);$entry=$container->get(\MyInvoice\Service\Accounting\PostingService::class)->postDocument($f['supplier'],'manual',null,[['account_code'=>'388.210','side'=>'debit','amount'=>'50000.00','dimensions'=>$dims,'dimension_origins'=>$origins],['account_code'=>'389.110','side'=>'credit','amount'=>'50000.00','dimensions'=>$dims,'dimension_origins'=>$origins]],['entry_date'=>'2026-12-31','posted_by'=>$f['actor']]);$owner=new \MyInvoice\Repository\Property\Services\Settlement\ServiceLifecycleRepository($this->db);$case=$owner->openCase($f['supplier'],$f['units']['U02'],$f['service']['id'],'2026-01-01','2026-12-31','service_balance_sheet','Synthetic documented reference service method',$f['actor'],'315.210');$owner->registerEstimate($f['supplier'],$case,[$entry],'Synthetic independently documented uncertain portion');$read=new ServiceReconciliation($this->db);$before=$read->at($f['supplier'],'2026-12-31');self::assertTrue($before['matches'],json_encode($before));self::assertSame('13200000',$before['totals']['324.110']);self::assertSame('8000000',$before['totals']['315.210']);self::assertSame('5000000',$before['totals']['388.210']);self::assertSame('5000000',$before['totals']['389.110']);
        (new \MyInvoice\Repository\AccountingPeriodRepository($this->db))->create($f['supplier'],2027,'2027-01-01','2027-12-31');$data=$d+compact('dims','owner','case')+['policy'=>'service_balance_sheet','invoice_amount'=>52000];$invoice=$this->native('invoice',$data);$owner->unwind($f['supplier'],$case,'2027-04-01',$f['actor']);$final=$owner->finalize($f['supplier'],$case,$invoice['invoice'],$invoice['line']['id'],'2027-04-01','Synthetic final invoice for uncertain portion only',$f['actor']);$after=$read->at($f['supplier'],'2027-04-01');self::assertTrue($after['matches'],json_encode($after));self::assertSame('13200000',$after['totals']['315.210']);self::assertSame('0',$after['totals']['388.210']);self::assertSame('0',$after['totals']['389.110']);self::assertSame($before['totals'],$read->at($f['supplier'],'2026-12-31')['totals']);
        $selector=$d['selector'];$selector['cost_line_id']=$final['cost_line_id'];$native=$container->get(\MyInvoice\Service\Property\Services\Settlement\SettlementOriginAdapter::class)->current($f['supplier'],$f['units']['U02'],$f['service']['id'],'2027-04-01',[$selector]);$facts=$d['doc']->snapshot();unset($facts['amounts']);$facts['actual_cents']='13200000';$facts['cost']=array_values($native['costs'])[0];self::assertSame('5200000',$facts['cost']['amount_cents']);$this->expectException(\DomainException::class);$this->expectExceptionMessage('settlement_cost_margin');\MyInvoice\Service\Property\Services\Settlement\SettlementDocument::fromEvidence($facts);
    }

    public function testUnprovedAnnualOpeningIsNotSilentlyExcluded():void
    {
        $d=$this->native('base','service_balance_sheet');$q=$this->db->pdo()->prepare("SELECT l.id FROM journal_entry_lines l JOIN journal_entries e ON e.supplier_id=l.supplier_id AND e.id=l.entry_id JOIN chart_of_accounts c ON c.supplier_id=l.supplier_id AND c.id=l.account_id WHERE l.supplier_id=? AND e.source_type='opening' AND c.account_code='388.210' ORDER BY l.id LIMIT 1");$q->execute([$d['f']['supplier']]);$line=(int)$q->fetchColumn();self::assertGreaterThan(0,$line);$this->db->pdo()->prepare('UPDATE journal_entry_lines SET amount=amount+0.01 WHERE supplier_id=? AND id=?')->execute([$d['f']['supplier'],$line]);$result=(new ServiceReconciliation($this->db))->at($d['f']['supplier'],'2027-01-01');self::assertFalse($result['matches']);self::assertContains($line,$result['unregistered_line_ids']);self::assertSame('incomplete',$result['coverage']);
    }

    public function testHistoricalOpeningKnownCostIsNotCountedAgainThroughItsSettlementDocument():void
    {
        $cross=(new \ReflectionProperty($this->fixture,'fixture'))->getValue($this->fixture);$historical=(new \ReflectionProperty($cross,'fixture'))->getValue($cross);$d=(new \ReflectionMethod($historical,'appliedFixture'))->invoke($historical,false);$f=$d['f'];$read=new ServiceReconciliation($this->db);$before=$read->at($f['supplier'],'2026-12-31');self::assertTrue($before['matches'],json_encode($before));self::assertSame('80000',$before['totals']['315.210']);self::assertSame('100000',$before['totals']['324.110']);$done=$d['owner']->apply($f['supplier'],$d['saved']['id'],$d['request'],0,$d['preview']['preview_hash'],'recon-s6-known-apply',$f['actor']);$after=$read->at($f['supplier'],'2026-12-31');self::assertTrue($after['matches'],json_encode($after));self::assertSame('0',$after['totals']['315.210']);self::assertSame('0',$after['totals']['324.110']);self::assertGreaterThan(0,$done['id']);
